    // track target and target version this was last edited in, so we can apply upgrade rules on import.
    cfg.targetVersions = Object.assign(Object.assign({}, cfg.targetVersions), { target: pxt.appTarget.versions.target, targetId: pxt.appTarget.id });
    // patch dependencies
